class Solution {
public:
    int singleNumber(vector<int>& nums) {
        unordered_map<int, int>store;
        for(int i=0; i<nums.size(); i++){
            store[nums[i]]++;
        }
        for(auto i : store){
            if(i.second == 1){
                return i.first;
            }
        }
        return -1;
    }
};
